def direct_queries(values, queries):
    answers = []
    for left, right in queries:
        if not 0 <= left <= right <= len(values):
            raise ValueError('invalid range')
        total = 0
        for index in range(left, right):
            total += values[index]
        answers.append(total)
    return answers

print(direct_queries([], [(0, 0)]))
print(direct_queries([2, -1, 3], [(0, 3), (1, 1), (1, 3)]))
print(direct_queries([7], []))
try:
    print(direct_queries([1], [(-1, 1)]))
except ValueError:
    print('ValueError')

def prepared_queries(values, queries):
    prefix = [0]
    for value in values:
        prefix.append(prefix[-1] + value)
    answers = []
    for left, right in queries:
        if not 0 <= left <= right <= len(values):
            raise ValueError('invalid range')
        answers.append(prefix[right] - prefix[left])
    return answers

print(prepared_queries([], [(0, 0)]))
print(prepared_queries([2, -1, 3], [(0, 3), (1, 1), (1, 3)]))
print(prepared_queries([7], []))
try:
    print(prepared_queries([1], [(-1, 1)]))
except ValueError:
    print('ValueError')

def operation_counts(size, queries):
    if size < 0:
        raise ValueError('size must be nonnegative')
    direct = 0
    differences = 0
    for left, right in queries:
        if not 0 <= left <= right <= size:
            raise ValueError('invalid range')
        direct += right - left
        differences += 1
    return direct, size, differences

print(operation_counts(6, [(0, 6), (0, 5), (1, 6), (2, 6)]))
print(operation_counts(3, []))
print(operation_counts(0, [(0, 0)]))
try:
    print(operation_counts(2, [(1, 3)]))
except ValueError:
    print('ValueError')
